<script setup lang="ts">
import {computed,ref,shallowRef,watch,onUnmounted} from 'vue';import {useApplication} from '../../application';import {ApiError} from '../../shared/api/client';import type {components} from '../../shared/api/generated';import {minutesVersionDiff,versionCategoryLabels,versionFields,type WorkspaceVersion} from './minutes-version-diff';
const props=defineProps<{meetingId:string;enabled:boolean;locked:boolean;revisionToken?:string}>(),emit=defineEmits<{restore:[snapshotId:string];denied:[cause:unknown]}>(),app=useApplication();
const items=shallowRef<components['schemas']['SavedWorkspaceSnapshot'][]>([]),next=ref<string|null>(null),leftId=ref(''),rightId=ref(''),left=shallowRef<WorkspaceVersion|null>(null),right=shallowRef<WorkspaceVersion|null>(null),error=ref(''),busy=ref(false),showAll=ref(false);let epoch=0,controller:AbortController|null=null;
const changes=computed(()=>left.value&&right.value?minutesVersionDiff(left.value,right.value):[]),fields=computed(()=>{if(!left.value||!right.value)return [];if(!showAll.value)return changes.value;const a=versionFields(left.value),b=versionFields(right.value),labels={title:'标题',body:'正文',...versionCategoryLabels,template:'模板与主题',exclusions:'敏感排除选择',background:'背景材料'};return Object.entries(labels).map(([key,label])=>({key,label,before:a[key]??'',after:b[key]??''}));});
function clear(){epoch++;controller?.abort();items.value=[];next.value=null;leftId.value='';rightId.value='';left.value=null;right.value=null;error.value='';busy.value=false;}
async function read(action:(signal:AbortSignal,accept:(fn:()=>void)=>void)=>Promise<void>){controller?.abort();const request=new AbortController();controller=request;const turn=++epoch;busy.value=true;error.value='';try{await action(request.signal,fn=>{if(turn===epoch&&!request.signal.aborted)fn();});}catch(cause){if(turn===epoch&&!request.signal.aborted){if(cause instanceof ApiError&&[401,403].includes(cause.status)){clear();emit('denied',cause);}else error.value=cause instanceof Error?cause.message:'版本暂不可读取';}}finally{if(turn===epoch)busy.value=false;}}
async function load(more=false){if(!props.enabled||!app.session.current.value)return;await read(async(signal,accept)=>{const page=await app.minutesInspection.workspaceHistory(props.meetingId,more?next.value:null,signal);accept(()=>{items.value=more?[...items.value,...page.items]:page.items;next.value=page.nextBeforeRevisionToken;if(!more){leftId.value=page.items[1]?.id??page.items[0]?.id??'';rightId.value=page.items[0]?.id??'';left.value=null;right.value=null;}});});if(leftId.value&&rightId.value)await compare();}
async function compare(){left.value=null;right.value=null;if(!leftId.value||!rightId.value)return;const a=leftId.value,b=rightId.value;await read(async(signal,accept)=>{const [one,two]=await Promise.all([app.minutesInspection.workspaceVersion(props.meetingId,a,signal),app.minutesInspection.workspaceVersion(props.meetingId,b,signal)]);accept(()=>{left.value=one;right.value=two;});});}
watch(()=>[props.meetingId,props.enabled,props.revisionToken,app.session.current.value?.actor.enterpriseId],()=>{clear();if(props.enabled&&app.session.current.value)void load();},{immediate:true});onUnmounted(clear);
</script>
<template><section class="workspace-versions" aria-label="完整版本比较与恢复"><h3>版本对比</h3><p class="small muted">每个完整版本记录正文、核心要素、行动字段、模板与排除设置。恢复会保存为新版本，已有历史保留，结论与行动需要重新核对。</p><div class="version-selectors"><label>较早版本<select v-model="leftId" :disabled="busy" @change="compare"><option v-for="item in items" :key="item.id" :value="item.id">版本 {{item.revisionToken}} · {{item.createdBy}} · {{item.createdAt}}</option></select></label><label>对比版本<select v-model="rightId" :disabled="busy" @change="compare"><option v-for="item in items" :key="item.id" :value="item.id">版本 {{item.revisionToken}} · {{item.createdBy}} · {{item.createdAt}}</option></select></label></div><div class="flex"><button v-if="next" class="btn sm" :disabled="busy" @click="load(true)">加载更早版本</button><button class="btn sm" :disabled="busy" @click="load()">刷新版本</button><label><input v-model="showAll" type="checkbox"/>显示全部内容</label></div><p v-if="busy" role="status">正在读取完整版本…</p><p v-if="error" role="alert">{{error}}</p><p v-if="!busy&&!items.length" class="muted">尚无完整关联快照；早期独立历史仍可在下方读取，不按时间猜测版本关联。</p><template v-if="left&&right"><p class="small">{{changes.length?changes.length+'项内容存在差异':'两个版本的内容与设置一致'}}</p><article v-for="field in fields" :key="field.key" class="version-difference"><h4>{{field.label}}</h4><div class="am-candidate-columns"><section><b>版本 {{left.snapshot.revisionToken}}</b><pre>{{field.before||'（无）'}}</pre></section><section><b>版本 {{right.snapshot.revisionToken}}</b><pre>{{field.after||'（无）'}}</pre></section></div></article><div class="am-candidate-columns version-restore"><section><p v-for="reason in left.restoreReasons" :key="reason" class="small">{{reason}}</p><button class="btn" :disabled="locked||busy||!left.canRestore" @click="emit('restore',left.snapshot.id)">恢复版本 {{left.snapshot.revisionToken}}</button></section><section><p v-for="reason in right.restoreReasons" :key="reason" class="small">{{reason}}</p><button class="btn" :disabled="locked||busy||!right.canRestore" @click="emit('restore',right.snapshot.id)">恢复版本 {{right.snapshot.revisionToken}}</button></section></div></template></section></template>
<style scoped>.workspace-versions{line-height:1.7}.version-selectors{display:flex;gap:16px;margin:16px 0}.version-selectors label{flex:1;min-width:0}.version-selectors select{display:block;max-width:100%;width:100%;padding:8px;border:1px solid var(--border);border-radius:4px}.version-difference{margin:16px 0}.version-difference pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:360px;overflow:auto;font:inherit;font-size:13px}.version-restore{margin-top:20px}.flex{gap:12px;align-items:center}.muted{color:var(--muted)}</style>
